/** Apply verified readytofight.cl stats onto a card by exact name match. */
export function applyVerifiedStats(card: CardDef): CardDef {
  if (card.type === 'Superstar') return card
  const v = R2F_VERIFIED[card.name]
  if (!v) return card
  return { ...card, fortitude: v.f, damage: v.d, stun: v.sv ?? card.stun, notes: dimMaybe(card.notes) }
}

function dimMaybe(notes: string | undefined): string | undefined {
  if (!notes) return undefined
  return notes
}
